import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])

    d_count = {}
    e_count = {}

    idx = 1
    for _ in range(n):
        m = int(input_data[idx])
        l = input_data[idx + 1]
        idx += 2

        if l == 'D':
            d_count[m] = d_count.get(m, 0) + 1
        else:
            e_count[m] = e_count.get(m, 0) + 1

    total_pairs = 0
    for m in range(30, 61):
        total_pairs += min(d_count.get(m, 0), e_count.get(m, 0))

    print(total_pairs)

if __name__ == '__main__':
    main()
